// Edge class for flow network
class Edge<Cap extends Number & Comparable<Cap>, Cost extends Number & Comparable<Cost>> implements Comparable<Edge<Cap, Cost>> {
    public int src, dst;
    public Cap cap;
    public Cost cost;
    public int rev;

    public Edge(int src, int dst, Cap cap, Cost cost, int rev) {
        this.src = src;
        this.dst = dst;
        this.cap = cap;
        this.cost = cost;
        this.rev = rev;
    }

    @Override
    public int compareTo(Edge<Cap, Cost> o) {
        // Not used for ordering, just to satisfy Comparable
        return 0;
    }
}

// Flow base class
class FlowBase<Cap extends Number & Comparable<Cap>, Cost extends Number & Comparable<Cost>> {
    protected ArrayList<ArrayList<Integer>> adj;
    public ArrayList<Edge<Cap, Cost>> edges;

    public FlowBase(int n) {
        adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        edges = new ArrayList<>();
    }

    public FlowBase(FlowBase<Cap, Cost> other) {
        this(other.size());
        edges.addAll(other.edges);
        for (int i = 0; i < other.size(); i++) {
            adj.get(i).addAll(other.adj.get(i));
        }
    }

    public int size() { return adj.size(); }

    public ArrayList<Integer> get(int node) { return adj.get(node); }

    public void addEdge(int src, int dst, Cap cap, Cost cost) {
        if (cap.compareTo(zero(cap)) <= 0) return;
        int fwd = edges.size();
        edges.add(new Edge<>(src, dst, cap, cost, fwd + 1));
        edges.add(new Edge<>(dst, src, zero(cap), negate(cost), fwd));
        adj.get(src).add(fwd);
        adj.get(dst).add(fwd + 1);
    }

    @SuppressWarnings("unchecked")
    private Cap zero(Cap cap) {
        if (cap instanceof Integer) return (Cap) Integer.valueOf(0);
        if (cap instanceof Long) return (Cap) Long.valueOf(0);
        throw new RuntimeException("Unsupported cap type");
    }

    @SuppressWarnings("unchecked")
    private Cost negate(Cost cost) {
        if (cost instanceof Integer) return (Cost) Integer.valueOf(-((Integer) cost));
        if (cost instanceof Long) return (Cost) Long.valueOf(-((Long) cost));
        throw new RuntimeException("Unsupported cost type");
    }
}

// Min-cost flow class
class MinCostFlow<Cap extends Number & Comparable<Cap>, Cost extends Number & Comparable<Cost>> extends FlowBase<Cap, Cost> {
    private Cost minCost;
    private Cost totalCost;
    private ArrayList<Cap> supp;
    private ArrayList<Cost> ptnl;
    private ArrayList<Cost> dist;
    private ArrayList<Integer> last;
    private final Cost INF;

    public MinCostFlow(int n) {
        super(n + 2);
        this.minCost = zeroCost();
        this.totalCost = zeroCost();
        supp = new ArrayList<>(Collections.nCopies(n + 2, zeroCap()));
        ptnl = new ArrayList<>(Collections.nCopies(n + 2, zeroCost()));
        dist = new ArrayList<>(Collections.nCopies(n + 2, zeroCost()));
        last = new ArrayList<>(Collections.nCopies(n + 2, -1));
        INF = null; // will be computed in Dijkstra
    }

    public MinCostFlow(MinCostFlow<Cap, Cost> other) {
        super(other);
        this.minCost = other.minCost;
        this.totalCost = other.totalCost;
        supp = new ArrayList<>(other.supp);
        ptnl = new ArrayList<>(other.ptnl);
        dist = new ArrayList<>(other.dist);
        last = new ArrayList<>(other.last);
        INF = null;
    }

    @Override
    public int size() { return super.size() - 2; }

    public void addEdge(int src, int dst, Cap cap, Cost cost) {
        if (src == dst) return;
        if (cap.compareTo(zeroCap()) <= 0) return;
        if (cost.compareTo(zeroCost()) < 0) {
            // negative cost edge -> reverse
            supp.set(src, sub(supp.get(src), cap));
            supp.set(dst, add(supp.get(dst), cap));
            minCost = add(minCost, mul(cost, cap));
            totalCost = sub(totalCost, mul(cost, cap));
            super.addEdge(dst, src, cap, neg(cost));
        } else {
            totalCost = add(totalCost, mul(cost, cap));
            super.addEdge(src, dst, cap, cost);
        }
    }

    public void supply(int node, Cap vol) {
        supp.set(node, add(supp.get(node), vol));
    }

    private boolean dijkstra(int src, int dst) {
        int n = super.size();
        Cost infty = add(totalCost, oneCost());
        for (int i = 0; i < n; i++) dist.set(i, infty);
        dist.set(src, zeroCost());
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long ndist = -top[0];
            int now = (int) top[1];
            if (ndist != longValue(dist.get(now))) continue;
            ptnl.set(now, add(ptnl.get(now), fromLong(ndist, dist.get(now))));
            dist.set(now, infty); // mark invalid
            for (int eid : adj.get(now)) {
                Edge<Cap, Cost> e = edges.get(eid);
                if (dist.get(e.dst).equals(infty) || e.cap.compareTo(zeroCap()) <= 0) continue;
                Cost newDist = sub(add(ptnl.get(now), e.cost), ptnl.get(e.dst));
                if (dist.get(e.dst).compareTo(newDist) > 0) {
                    dist.set(e.dst, newDist);
                    last.set(e.dst, eid);
                    pq.offer(new long[]{-longValue(newDist), e.dst});
                }
            }
        }
        return !dist.get(dst).equals(infty);
    }

    public boolean solve() {
        int base = super.size();
        if (base <= 1) return false;
        int src = base - 2;
        int dst = src + 1;
        Cap flow = zeroCap();
        Cap suppSum = zeroCap();
        for (int i = 0; i < base; i++) {
            suppSum = add(suppSum, supp.get(i));
            if (supp.get(i).compareTo(zeroCap()) > 0) {
                flow = add(flow, supp.get(i));
                addEdge(src, i, supp.get(i), zeroCost());
            } else if (supp.get(i).compareTo(zeroCap()) < 0) {
                addEdge(i, dst, neg(supp.get(i)), zeroCost());
            }
            supp.set(i, zeroCap());
        }
        if (suppSum.compareTo(zeroCap()) != 0) return false;
        while (flow.compareTo(zeroCap()) > 0) {
            if (!dijkstra(src, dst)) return false;
            Cap resid = flow;
            int node = dst;
            while (node != src) {
                Edge<Cap, Cost> e = edges.get(last.get(node));
                resid = min(resid, e.cap);
                node = e.src;
            }
            flow = sub(flow, resid);
            minCost = add(minCost, mul(ptnl.get(dst), resid));
            node = dst;
            while (node != src) {
                Edge<Cap, Cost> e = edges.get(last.get(node));
                e.cap = sub(e.cap, resid);
                edges.get(e.rev).cap = add(edges.get(e.rev).cap, resid);
                node = e.src;
            }
        }
        return true;
    }

    public Cost optimal() {
        if (solve()) return minCost;
        else return null; // should not happen
    }

    // Utility methods for number operations (assuming Integer or Long)
    @SuppressWarnings("unchecked")
    private Cap zeroCap() {
        return (Cap) (Object) 0;
    }

    @SuppressWarnings("unchecked")
    private Cost zeroCost() {
        return (Cap) (Object) 0; // Actually we need Cost type, but since cost can be long, we handle generically
    }

    private Cost oneCost() {
        // Need to return 1 of type Cost
        if (totalCost instanceof Integer) return (Cost) (Object) 1;
        if (totalCost instanceof Long) return (Cost) (Object) 1L;
        throw new RuntimeException("Unsupported cost type");
    }

    private long longValue(Cost c) {
        if (c instanceof Integer) return ((Integer) c).longValue();
        if (c instanceof Long) return (Long) c;
        throw new RuntimeException("Unsupported cost type");
    }

    private Cost fromLong(long l, Cost prototype) {
        if (prototype instanceof Integer) return (Cost) (Object) (int) l;
        if (prototype instanceof Long) return (Cost) (Object) l;
        throw new RuntimeException("Unsupported cost type");
    }

    @SuppressWarnings("unchecked")
    private Cap add(Cap a, Cap b) {
        if (a instanceof Integer) return (Cap) (Object) (((Integer) a) + ((Integer) b));
        if (a instanceof Long) return (Cap) (Object) (((Long) a) + ((Long) b));
        throw new RuntimeException("Unsupported cap type");
    }

    @SuppressWarnings("unchecked")
    private Cap sub(Cap a, Cap b) {
        if (a instanceof Integer) return (Cap) (Object) (((Integer) a) - ((Integer) b));
        if (a instanceof Long) return (Cap) (Object) (((Long) a) - ((Long) b));
        throw new RuntimeException("Unsupported cap type");
    }

    @SuppressWarnings("unchecked")
    private Cost add(Cost a, Cost b) {
        if (a instanceof Integer) return (Cost) (Object) (((Integer) a) + ((Integer) b));
        if (a instanceof Long) return (Cost) (Object) (((Long) a) + ((Long) b));
        throw new RuntimeException("Unsupported cost type");
    }

    @SuppressWarnings("unchecked")
    private Cost sub(Cost a, Cost b) {
        if (a instanceof Integer) return (Cost) (Object) (((Integer) a) - ((Integer) b));
        if (a instanceof Long) return (Cost) (Object) (((Long) a) - ((Long) b));
        throw new RuntimeException("Unsupported cost type");
    }

    @SuppressWarnings("unchecked")
    private Cost mul(Cost a, Cap b) {
        if (a instanceof Integer && b instanceof Integer)
            return (Cost) (Object) (((Integer) a) * ((Integer) b));
        if (a instanceof Long && b instanceof Long)
            return (Cost) (Object) (((Long) a) * ((Long) b));
        throw new RuntimeException("Unsupported type for multiplication");
    }

    @SuppressWarnings("unchecked")
    private Cap neg(Cap a) {
        if (a instanceof Integer) return (Cap) (Object) (-((Integer) a));
        if (a instanceof Long) return (Cap) (Object) (-((Long) a));
        throw new RuntimeException("Unsupported cap type");
    }

    @SuppressWarnings("unchecked")
    private Cost neg(Cost a) {
        if (a instanceof Integer) return (Cost) (Object) (-((Integer) a));
        if (a instanceof Long) return (Cost) (Object) (-((Long) a));
        throw new RuntimeException("Unsupported cost type");
    }

    @SuppressWarnings("unchecked")
    private Cap min(Cap a, Cap b) {
        if (a instanceof Comparable) return ((Comparable<Cap>) a).compareTo(b) < 0 ? a : b;
        throw new RuntimeException("Unsupported cap type");
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
