            mcf.supply(j, 1);
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int nu = u + n;
            int nv = v + n;
            for (int t = 0; t < tlim; t++) {
                for (int x = 0; x < k; x++) {
                    mcf.addEdge(u, nv, 1, (long) c + d * (2L * x + 1));
                    mcf.addEdge(v, nu, 1, (long) c + d * (2L * x + 1));
                }
                u = nu;
                v = nv;
                nu += n;
                nv += n;
            }
        }

        for (int i = 1; i < n; i++) {
            for (int t = 0; t < tlim; t++) {
                mcf.addEdge(n * t + i, n * (t + 1) + i, k, c);
            }
        }

        int dst = mcf.size() - 1;
        mcf.supply(dst, -k);
        for (int t = 0; t <= tlim; t++) {
            mcf.addEdge(t * n, dst, k, 0);
        }

        System.out.println(mcf.optimal());
    }
